"use strict";Object.defineProperty(exports,Symbol.toStringTag,{value:"Module"});class s{constructor(e="app"){this.prefix=e}getKey(e){return`${this.prefix}:${e}`}setLocal(e,t,r){const o={value:t,expiry:r?Date.now()+r:null};localStorage.setItem(this.getKey(e),JSON.stringify(o))}getLocal(e){const t=localStorage.getItem(this.getKey(e));if(!t)return null;try{const r=JSON.parse(t);return r.expiry&&Date.now()>r.expiry?(this.removeLocal(e),null):r.value}catch(r){return console.error("解析存储数据失败:",r),null}}removeLocal(e){localStorage.removeItem(this.getKey(e))}setSession(e,t){sessionStorage.setItem(this.getKey(e),JSON.stringify(t))}getSession(e){const t=sessionStorage.getItem(this.getKey(e));if(!t)return null;try{return JSON.parse(t)}catch(r){return console.error("解析存储数据失败:",r),null}}removeSession(e){sessionStorage.removeItem(this.getKey(e))}clear(e="all"){(e==="local"||e==="all")&&Object.keys(localStorage).filter(t=>t.startsWith(this.prefix)).forEach(t=>localStorage.removeItem(t)),(e==="session"||e==="all")&&Object.keys(sessionStorage).filter(t=>t.startsWith(this.prefix)).forEach(t=>sessionStorage.removeItem(t))}}exports.StorageService=s;
